CREATE TABLE IF NOT EXISTS ba_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS ba_session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL, "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES ba_user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ba_account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES ba_user(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS ba_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz, "updatedAt" timestamptz);
CREATE TABLE IF NOT EXISTS app_admins (user_id text PRIMARY KEY REFERENCES ba_user(id));
CREATE TABLE IF NOT EXISTS farms (id uuid PRIMARY KEY, name text NOT NULL, municipality text, year int NOT NULL, currency text NOT NULL CHECK(currency IN ('RSD','EUR')), owner_id text NOT NULL REFERENCES ba_user(id), basis text NOT NULL DEFAULT 'Iznosi kako su evidentirani; bez poreskog obračuna');
CREATE TABLE IF NOT EXISTS memberships (farm_id uuid NOT NULL REFERENCES farms(id), user_id text NOT NULL REFERENCES ba_user(id), role text NOT NULL CHECK(role IN ('owner','member')), PRIMARY KEY(farm_id,user_id));
CREATE TABLE IF NOT EXISTS source_imports (hash text PRIMARY KEY, name text NOT NULL, imported_at timestamptz NOT NULL DEFAULT now(), inventory jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS source_sheets (id text PRIMARY KEY, source_hash text NOT NULL REFERENCES source_imports(hash), original_name text NOT NULL, position int NOT NULL, role text NOT NULL, inventory jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS templates (id text PRIMARY KEY, sheet_id text NOT NULL REFERENCES source_sheets(id), name text NOT NULL, basis text NOT NULL, reference numeric NOT NULL, intensity text, model jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS norm_versions (id uuid PRIMARY KEY, template_id text NOT NULL REFERENCES templates(id), name text NOT NULL, status text NOT NULL CHECK(status IN ('draft','active','archive')), valid_from date NOT NULL, valid_to date NOT NULL, author text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL, model jsonb NOT NULL, CHECK(valid_from<=valid_to));
CREATE TABLE IF NOT EXISTS production_periods (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), template_id text NOT NULL REFERENCES templates(id), name text NOT NULL, year int NOT NULL, details jsonb NOT NULL, status text NOT NULL DEFAULT 'draft', actual_complete boolean NOT NULL DEFAULT false, UNIQUE(id,farm_id));
CREATE TABLE IF NOT EXISTS exchange_rates (id uuid PRIMARY KEY, valid_from date NOT NULL UNIQUE, valid_to date NOT NULL, rate numeric(20,8) NOT NULL CHECK(rate>0), source_url text NOT NULL, published_at date NOT NULL, checked_at timestamptz NOT NULL DEFAULT now(), author text NOT NULL, CHECK(valid_to>=valid_from));
CREATE TABLE IF NOT EXISTS business_events (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), production_id uuid, kind text NOT NULL CHECK(kind IN ('sale','cost','subsidy','other_income')), date date, title text NOT NULL, status text NOT NULL, money jsonb, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,farm_id), FOREIGN KEY(production_id,farm_id) REFERENCES production_periods(id,farm_id));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), event_id uuid, date date NOT NULL, direction text NOT NULL CHECK(direction IN ('in','out','own_transfer')), category text NOT NULL, money jsonb NOT NULL, note text, FOREIGN KEY(event_id,farm_id) REFERENCES business_events(id,farm_id));
CREATE TABLE IF NOT EXISTS inventory_movements (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), production_id uuid, date date NOT NULL, product text NOT NULL, stock_type text NOT NULL DEFAULT 'product', unit text NOT NULL, quantity numeric NOT NULL, kind text NOT NULL, value_rsd numeric, value_eur numeric, method text, link_id uuid, note text, FOREIGN KEY(production_id,farm_id) REFERENCES production_periods(id,farm_id));
CREATE TABLE IF NOT EXISTS internal_transfers (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), from_production uuid NOT NULL, to_production uuid NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), product text NOT NULL, unit text NOT NULL, value_rsd numeric NOT NULL, value_eur numeric NOT NULL, method text NOT NULL, date date NOT NULL, FOREIGN KEY(from_production,farm_id) REFERENCES production_periods(id,farm_id), FOREIGN KEY(to_production,farm_id) REFERENCES production_periods(id,farm_id), CHECK(from_production<>to_production));
CREATE TABLE IF NOT EXISTS feed_consumption (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), production_id uuid NOT NULL, date date NOT NULL, product text NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), unit text NOT NULL, value_rsd numeric NOT NULL, value_eur numeric NOT NULL, origin text NOT NULL, norm_item_id text, FOREIGN KEY(production_id,farm_id) REFERENCES production_periods(id,farm_id));
CREATE TABLE IF NOT EXISTS opening_balances (farm_id uuid NOT NULL REFERENCES farms(id), year int NOT NULL, money jsonb NOT NULL, PRIMARY KEY(farm_id,year));
CREATE TABLE IF NOT EXISTS wip_observations (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), production_id uuid NOT NULL, month date NOT NULL, money jsonb NOT NULL, note text NOT NULL, FOREIGN KEY(production_id,farm_id) REFERENCES production_periods(id,farm_id), UNIQUE(farm_id,production_id,month));
CREATE TABLE IF NOT EXISTS report_snapshots (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), production_id uuid, generated_at timestamptz NOT NULL DEFAULT now(), previous_id uuid REFERENCES report_snapshots(id), payload jsonb NOT NULL, FOREIGN KEY(production_id,farm_id) REFERENCES production_periods(id,farm_id));
CREATE TABLE IF NOT EXISTS data_sources (id text PRIMARY KEY, name text NOT NULL, url text NOT NULL, terms text NOT NULL, checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS statistic_series (id text PRIMARY KEY, source_id text NOT NULL REFERENCES data_sources(id), product text NOT NULL, indicator text NOT NULL, definition text NOT NULL, mapping text NOT NULL, geography text NOT NULL, unit text NOT NULL, currency text, price_type text, source_url text NOT NULL);
CREATE TABLE IF NOT EXISTS observations (id uuid PRIMARY KEY, series_id text NOT NULL REFERENCES statistic_series(id), period int NOT NULL, value numeric, status text NOT NULL, published_at date NOT NULL, retrieved_at timestamptz NOT NULL DEFAULT now(), source_url text NOT NULL, revision int NOT NULL DEFAULT 1, history jsonb NOT NULL DEFAULT '[]', UNIQUE(series_id,period));
CREATE TABLE IF NOT EXISTS buyers (id uuid PRIMARY KEY, name text NOT NULL, products text NOT NULL, area text NOT NULL, contact text NOT NULL, source_url text NOT NULL, verified_at date NOT NULL);
CREATE TABLE IF NOT EXISTS buyer_offers (id uuid PRIMARY KEY, buyer_id uuid NOT NULL REFERENCES buyers(id), product text NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), unit text NOT NULL, quality text NOT NULL, delivery text NOT NULL, period text NOT NULL, expires_at date NOT NULL, source_url text NOT NULL, verified_at date NOT NULL, approved boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS market_requirements (id uuid PRIMARY KEY, buyer_id uuid REFERENCES buyers(id), product text NOT NULL, market text NOT NULL, kind text NOT NULL, description text NOT NULL, source_url text NOT NULL, verified_at date NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id uuid PRIMARY KEY, farm_id uuid REFERENCES farms(id), user_id text NOT NULL, action text NOT NULL, entity text NOT NULL, at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS events_farm ON business_events(farm_id,date);
CREATE INDEX IF NOT EXISTS stock_farm ON inventory_movements(farm_id,product,unit);
CREATE INDEX IF NOT EXISTS payments_farm ON payments(farm_id,date);
CREATE INDEX IF NOT EXISTS audit_farm ON audit_log(farm_id,at);
